from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/bike_sharing/pipeline_lab.json").read_text(encoding="utf-8")
)
late_events = lab["events"]["late_fixture"]

def lookup_features(rows, target, asof, ignore_avail=False):
    lag1 = None
    lag7 = None
    w_sum = 0
    w_cnt = 0
    newest = None
    for r in rows:
        e = r["event_day"]
        avail_ok = True if ignore_avail else (r["available_day"] <= asof)
        if e < target and avail_ok:
            if newest is None or e > newest:
                newest = e
            if e == target - 1:
                lag1 = r["cnt"]
            if e == target - 7:
                lag7 = r["cnt"]
            if target - 7 <= e < target:
                w_sum += r["cnt"]
                w_cnt += 1
    mean7 = round(w_sum / w_cnt, 2) if w_cnt > 0 else None
    age = (target - 1 - newest) if newest is not None else None
    return {"lag1": lag1, "lag7": lag7, "mean7": mean7, "observed7": w_cnt, "age_days": age}

for t in [365, 375, 409, 545]:
    pit = lookup_features(late_events, t, t, ignore_avail=False)
    latest = lookup_features(late_events, t, t, ignore_avail=True)
    changed = []
    for k in ["lag1", "lag7", "mean7", "observed7", "age_days"]:
        if pit[k] != latest[k]:
            changed.append(k)
    print(f"day {t} | PIT={pit} | diff_vs_latest={changed}")

pit_375 = lookup_features(late_events, 375, 375, ignore_avail=False)
lat_375 = lookup_features(late_events, 375, 375, ignore_avail=True)
assert pit_375["lag1"] is None and lat_375["lag1"] == 3598

### Pure Python কোডের যাচাইকৃত Output
```text
day 365 | PIT={'lag1': 2485, 'lag7': 754, 'mean7': 1920.29, 'observed7': 7, 'age_days': 0} | diff_vs_latest=[]
day 375 | PIT={'lag1': None, 'lag7': 2368, 'mean7': 3343.33, 'observed7': 6, 'age_days': 1} | diff_vs_latest=['lag1', 'mean7', 'observed7', 'age_days']
day 409 | PIT={'lag1': None, 'lag7': 4375, 'mean7': 3089.33, 'observed7': 6, 'age_days': 1} | diff_vs_latest=['lag1', 'mean7', 'observed7', 'age_days']
day 545 | PIT={'lag1': None, 'lag7': 5823, 'mean7': 6954.67, 'observed7': 6, 'age_days': 1} | diff_vs_latest=['lag1', 'mean7', 'observed7', 'age_days']
```
দেখুন: `day 365`-এ কোনো বিলম্বিত দিন ছিল না বলে `diff = []`, কিন্তু `day 375`, `409` এবং `545`—তিনটিতেই `latest` ব্যবহার করলে এক ধাক্কায় ৪টি Feature (`lag1`, `mean7`, `observed7`, `age_days`) বদলে যাচ্ছে!

### Option B — একাধিক Revision-এ সঠিক ক্রম (`Filter -> Latest`) বনাম ভুল ক্রম (`Latest -> Filter`)
চলুন ছোট ৩-সারির ডেটায় হাতে-কলমে প্রমাণ করি কেন আগে `available <= asof` চালাতে হয়:

```python
versions = [
    {"day": 1, "available": 2, "revision": 1, "value": 10.0},
    {"day": 1, "available": 5, "revision": 2, "value": 12.0},
    {"day": 2, "available": 3, "revision": 1, "value": 20.0},
]

def rev_sort_key(row):
    return (row["available"], row["revision"])

def safe_snapshot(target_day, asof):
    latest = {}
    for ev in sorted(versions, key=rev_sort_key):
        if (target_day - 7 <= ev["day"] < target_day) and (ev["available"] <= asof):
            latest[ev["day"]] = ev["value"]
    total = 0.0
    for v in latest.values():
        total += v
    return latest, total / len(latest)

def buggy_latest_first(target_day, asof):
    # ভুল ক্রম: আগে সবার সর্বশেষ Revision নেওয়া, তারপর avail <= asof ছাঁকা!
    all_latest = {}
    for ev in sorted(versions, key=rev_sort_key):
        all_latest[ev["day"]] = ev
    kept = {}
    for d, ev in all_latest.items():
        if (target_day - 7 <= d < target_day) and (ev["available"] <= asof):
            kept[d] = ev["value"]
    total = 0.0
    for v in kept.values():
        total += v
    return kept, total / len(kept)

hist_map, hist_mean = safe_snapshot(4, 4)
corr_map, corr_mean = safe_snapshot(4, 6)
bug_map, bug_mean = buggy_latest_first(4, 4)

assert hist_map[1] == 10.0 and corr_map[1] == 12.0
print(f"SAFE  asof=4 (Historical): {hist_map} -> mean={hist_mean:.1f}")
print(f"SAFE  asof=6 (Corrected):  {corr_map} -> mean={corr_mean:.1f}")
print(f"BUGGY asof=4 (Lost day 1!): {bug_map} -> mean={bug_mean:.1f}")
```

**Python যাচাইকৃত Output:**
```text
SAFE  asof=4 (Historical): {1: 10.0, 2: 20.0} -> mean=15.0
SAFE  asof=6 (Corrected):  {1: 12.0, 2: 20.0} -> mean=16.0
BUGGY asof=4 (Lost day 1!): {2: 20.0} -> mean=20.0
```
*(চমৎকার প্রমাণ! ভুল ক্রমে `day 1`-এর বৈধ `rev 1 (10.0)` পুরোপুরি উধাও হয়ে গড় ভুলভাবে `20.0` হয়ে গেল!)*

