from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/bike_sharing/pipeline_lab.json").read_text(encoding="utf-8")
)
rows = lab["events"]["late_fixture"]
store = {}
for row in rows + rows:
    key = row["event_key"]
    if key not in store:
        store[key] = row
    else:
        assert store[key] == row
result = len(store)
print(result)
